import {t} from './locales.js';import {cowFollowups} from './cow-missions.js';
/** Read-only actual achievement progress. @param {import('./engine.js').State} state @param {HTMLElement} host */
export function renderCowGoals(state,host){if((state.cow?.mission.step||0)<8)return;const box=document.createElement('section'),heading=document.createElement('h3'),list=document.createElement('ul');box.id='cow-goals';heading.textContent=t('cowDairyGoals');for(const goal of cowFollowups(state)){const item=document.createElement('li'),title=document.createElement('strong'),detail=document.createElement('p');item.dataset.cowGoal=goal.id;item.dataset.complete=String(!!state.cow?.grants.includes(goal.id));title.textContent=t(goal.title)+' · '+(state.cow?.grants.includes(goal.id)?t('cowGoalComplete'):goal.progress);detail.textContent=t(goal.detail);item.append(title,detail);list.append(item);}box.append(heading,list);host.append(box);}
